from pathlib import Path
import pandas as pd,matplotlib.pyplot as plt
from matplotlib.ticker import FixedLocator, FixedFormatter
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results'/'figures';d=pd.read_csv(ROOT/'data'/'processed'/'PratxKapp_consistent_Dmax_scan.csv');sm=pd.read_csv(ROOT/'data'/'processed'/'PratxKapp_transfer_summary.csv');conv=float(sm.loc[sm.design=='CONV only','scaled_Jacobian_condition_number'].iloc[0]);bp=4/0.42
fig,ax=plt.subplots(figsize=(6.3,4.5));ax.plot(d.max_FLASH_dose_Gy,d.scaled_Jacobian_condition_number,marker='o',lw=2);ax.axvline(bp,ls='--',lw=1.6,label=f'Depletion breakpoint ({bp:.2f} Gy)');ax.axhline(conv,ls=':',lw=1.6,label=f'CONV only ({conv:.1f})');ax.set_yscale('log');ticks=[30,100,300,600];ax.yaxis.set_major_locator(FixedLocator(ticks));ax.yaxis.set_major_formatter(FixedFormatter([str(x) for x in ticks]));ax.set_xlabel('Maximum FLASH dose (Gy)');ax.set_ylabel('Scaled Jacobian condition number');ax.legend(frameon=True,framealpha=1,fontsize=9.5);ax.grid(alpha=.2,which='both');fig.tight_layout();fig.savefig(OUT/'FigureS1_final.png',dpi=300,bbox_inches='tight');fig.savefig(OUT/'FigureS1_final.pdf',bbox_inches='tight');plt.close(fig)
